const toRad = d => d * Math.PI / 180;

// Location 1: Device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Location 2: Boston, MA 02118 (South End) — approximate coordinates
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const R = 6371; // Earth radius in km
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 +
          Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
const distKm = R * c;
const distMi = distKm * 0.621371;

console.log('=== Distance Calculation ===');
console.log('');
console.log('From: Your device location');
console.log('  Latitude:  ' + lat1);
console.log('  Longitude: ' + lon1);
console.log('  (San Francisco, CA area)');
console.log('');
console.log('To:   Order #W4705780 shipping address');
console.log('  4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('  Latitude:  ' + lat2 + ' (approx)');
console.log('  Longitude: ' + lon2 + ' (approx)');
console.log('');
console.log('=== Result ===');
console.log('  Straight-line distance: ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g,',') + ' km (' + distMi.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g,',') + ' miles)');
"
